out = ROOT / "delivery" / "archeval" / "pad_arch_eval.json"
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(doc, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
cfg, h = E.load_config(out)
print("written", h)
